  'about.bookshopLeadIn': "Hecho por la misma pequeña empresa que lleva nuestra librería:",
  "about.eyebrow": "Acerca de Luminous StockHaven",
  "about.pageTitle": "Luminous StockHaven — Acerca de",
  "about.founderHeading": "📖 Sobre la fundadora",
  "about.founder.p1": "Hola, soy Concepcion, la fundadora de Luminous StockHaven.",
  "about.founder.p2": "No vengo de una gran empresa tecnológica ni me siento en una oficina corporativa. Soy una pequeña comerciante, igual que tú. Administro cinco tiendas en línea, especializadas en libros y accesorios artesanales para amantes de los libros.\nComo muchos comerciantes independientes, llegué a un punto límite tratando de administrar el inventario de varias ubicaciones, llevar la cuenta de los ISBN de las editoriales junto con mis propios SKU artesanales y manejar los pedidos a proveedores con hojas de cálculo torpes. Cuando busqué una aplicación que me ayudara, probé seis opciones diferentes. Todas eran completamente incompletas, increíblemente confusas o abusivas: cobraban cientos de dólares al mes por herramientas básicas.",
  "about.founder.p3": "Frustrada con una industria que exprime a los creadores independientes, decidí construir mi propia solución. Construí Luminous StockHaven por necesidad, para llevar mis propios negocios de forma limpia, eficiente y con total tranquilidad.",
  "about.founder.p4": "Decidí abrir esta plataforma al público a un precio honesto y accesible porque todo pequeño comerciante merece herramientas que de verdad funcionen sin poner en riesgo sus ganancias. Somos una empresa independiente, protegemos con firmeza a nuestra comunidad y fuimos creados por una comerciante, para comerciantes.",
