  "notice.heading": "🛡️ Hecho para comerciantes, sin precio para los buitres corporativos",
  "notice.intro": "Construí esta aplicación porque administro 5 tiendas y estaba harta de que me estafaran con software confuso de cientos de dólares. Esta aplicación se creó para proteger a artistas independientes, artesanos, libreros y tiendas locales.",
