  "plans.backToWelcome": "Volver a la bienvenida",
  "plans.eyebrow": "Planes y funciones",
  "plans.title": "Comparar los planes de StockHaven",
  "plans.intro": "Una sola cuenta, elijas el plan que elijas: Business cubre hasta cinco negocios. Los precios son mensuales en dólares estadounidenses, y los nuevos clientes web que cumplan los requisitos pueden recibir una prueba de siete días entre Essentials y Business. Pasar una suscripción Essentials existente a Business no reinicia la prueba ni crea otra prueba gratuita. Los precios de los planes web no incluyen los impuestos aplicables, si los hubiera. Tu cargo exacto se mostrará antes de que autorices una suscripción.",
  "plans.availableAtLaunch": "Disponible en el lanzamiento móvil",
