  "plans.mobileIncludedNote": "Ambos planes web incluyen el compañero móvil, así que un suscriptor web nunca paga también la cuota mensual móvil.",
  "plans.priceNote": "Essentials cuesta $14.99/mes más los impuestos aplicables, si los hubiera. Business cuesta $29.99/mes más los impuestos aplicables, si los hubiera. Cualquier impuesto requerido se determina durante el pago con el proveedor y debe aparecer en el total final antes del pago. Esta página de comparación no es una cotización de impuestos ni una autorización de pago.",
  "plans.mobilePriceNote": "El plan solo móvil cuesta $4.99/mes a su precio base previsto en EE. UU. La App Store o Google Play muestra el precio de suscripción local real y los impuestos aplicables antes de la compra. Sus límites de productos, sitios y personal se establecen en el lanzamiento, por separado de los niveles web.",
  "plans.planChangeNote": "Un cambio de plan web debe ser confirmado por el proveedor de facturación. El nuevo precio, la fecha de entrada en vigor y cualquier prorrateo se explicarán antes de que se autorice el cambio. Una mejora no debería crear una segunda suscripción.",
  "plans.providerNote": "Los precios, los cargos y las pruebas los gestiona el proveedor a través del cual te suscribes (la App Store, Google Play, el sitio web o Shopify), nunca esta página.",
