  "upgrade.trialHistoryNote": "Si estás pagando Essentials y pasas a Business, conservas la misma cuenta de cliente y el mismo historial de pruebas. Business no incluye una prueba adicional de siete días. Si mejoras de plan mientras tu prueba original sigue activa, su fecha de finalización original no se restablece.",
  "upgrade.providerConfirmNote": "Los cambios de plan requieren la confirmación del proveedor de facturación. Cualquier diferencia de precio, prorrateo y fecha de entrada en vigor debe mostrarse antes de que apruebes el cambio. Una mejora no debe crear una segunda suscripción simultánea.",
  "upgrade.chargedThroughProviderNote": "Los cambios de plan se cobran a través del proveedor de facturación. Puedes cancelar tu suscripción desde esta página con el botón Cancelar suscripción situado bajo tu plan actual, o desde Ajustes. Cancelar detiene las renovaciones futuras al final de tu periodo pagado; nunca pone fin a tu acceso de inmediato. Los espacios de trabajo gratuitos existentes no se cobran por ver estas opciones.",
  "billing.cancel.title": "Cancelar suscripción",
