  "billing.cancel.alreadyCanceledNoEnd": "Termina al final del periodo pagado actual. Conservas el acceso completo hasta entonces.",
  "billing.cancel.appStoreNote": "Si alguna vez te suscribes a través de Google Play o la Apple App Store, es posible que tengas que cancelarla desde los ajustes de suscripciones de esa tienda. Este cuadro de diálogo no puede detener la facturación de una tienda de aplicaciones. Desinstalar la aplicación o eliminar tu cuenta de StockHaven no cancela una suscripción de tienda.",
