  "exports.eyebrow": "Datos",
  "exports.title": "Exportaciones y copias de seguridad",
  "exports.subtitleStart": "Las descargas están siempre limitadas a",
  "exports.subtitleRest": ". Cada archivo lleva el nombre de la empresa y la fecha en que se creó.",
  "exports.createBusinessFirst": "Cread primero una empresa: las exportaciones pertenecen a una empresa, no a la aplicación.",
  "exports.lockedTitle": "Las exportaciones en CSV y Excel son una función de Business",
  "exports.lockedDesc": "Vuestro espacio de trabajo tiene el plan Essentials. Business añade exportaciones en CSV y Excel, valoración de existencias, productos y personal ilimitados, proveedores, compras y packs.",
  "exports.seeBusiness": "Ver qué incluye Business",
  "exports.whatTheseAre": "Qué son estos archivos",
  "exports.about1": "Cada conjunto de datos viene en CSV o en un libro de Excel real (.xlsx): el libro completo de inventario es solo en Excel, con una hoja por conjunto de datos. Los archivos CSV se abren en Excel, Numbers, Google Sheets y la mayoría de las aplicaciones de existencias. El texto UTF-8, las comas entre comillas, los saltos de línea en las notas y los ceros a la izquierda en los códigos se conservan, y las celdas que empiezan como una fórmula se neutralizan para que la hoja de cálculo las abra como texto.",
  "exports.about2": "En los archivos de Excel, los SKU, UPC, ISBN y códigos de barras son celdas de texto, nunca notación científica y nunca ceros recortados, con anchos de columna, filtros de encabezado y formatos de moneda o cantidad aplicados. El libro completo de inventario mantiene los productos, los niveles de existencias, las ubicaciones y los movimientos en hojas separadas.",
  "exports.about3": "Las exportaciones muy grandes se detienen en 20.000 filas por conjunto de datos: cuando eso ocurre, el nombre del archivo lo indica (truncated-20000), para que un archivo parcial nunca pase por completo.",
  "exports.about4": "Una copia de seguridad es una instantánea de vuestros datos, no una restauración con un clic. Restaurarla es un trabajo manual y con revisión previa, así que guardad el archivo en un lugar seguro: de momento, nada en la aplicación puede recrear desde él una empresa eliminada. El código de la aplicación y las copias de la plataforma Base44 se gestionan aparte de estos archivos.",
  "exports.about5": "Las fotos y los archivos adjuntos figuran como sus enlaces almacenados: los archivos de imagen en sí no se incluyen en la descarga.",
  "exports.backupTitle": "Copia de seguridad completa",
  "exports.backupDesc": "Un archivo con los productos, ubicaciones, niveles de existencias, libro completo de movimientos, proveedores, compras, pedidos, devoluciones, recuentos y anuncios de esta empresa, además de los ajustes de su perfil. Guardadlo en un lugar que controléis.",
  "exports.backupIncludes1": "Productos, códigos, costes y notas",
  "exports.backupIncludes2": "Ubicaciones y cantidades por ubicación",
  "exports.backupIncludes3": "Cada movimiento, con autor y hora",
  "exports.backupIncludes4": "Compras, pedidos, devoluciones y recuentos",
