  "import.eyebrow": "Datos",
  "import.title": "Centro de importación",
  "import.subtitleStart": "Tres operaciones de hoja de cálculo separadas, para que una corrección de precios nunca llegue como una recepción de existencias. Todo llega solo a",
  "import.subtitleRest": ", y no se escribe nada hasta que una prueba en seco ha salido bien.",
  "import.createBusinessFirst": "Cread primero una empresa: los productos importados pertenecen a una empresa.",
  "import.createBusinessFirstShort": "Cread primero una empresa.",
  "import.whatEachDoes": "Qué hace cada operación",
  "import.createTitle": "Crear productos nuevos",
  "import.createDesc": "añade filas que aún no están en el catálogo. Los SKU y códigos de barras duplicados que ya están en uso se omiten, y el stock inicial puede llegar a una ubicación que elijáis como recepción.",
  "import.updateTitle": "Actualizar productos existentes",
  "import.updateDesc": "hace coincidir cada fila por SKU o ID de registro y muestra el valor antiguo junto al nuevo propuesto. Las celdas en blanco dejan el valor guardado como está, salvo que pidáis que se borren los blancos, y las cantidades nunca se tocan.",
  "import.receiveModeTitle": "Recibir existencias",
  "import.receiveModeDesc": "añade las cantidades que llegan a una ubicación y escribe una recepción en el libro de movimientos por cada línea. Cada lote queda marcado, para que la misma hoja no pueda recibirse dos veces.",
  "import.excelNote": "Los libros de Excel (.xlsx) se leen directamente: elegid la hoja de trabajo y las columnas se hacen coincidir por vosotros. Los códigos se mantienen enteros: un UPC guardado como texto conserva sus dígitos y ceros a la izquierda. Las filas que no se pueden importar se enumeran con un motivo",
