  "print.supplierBlockedDesc": "Los documentos de proveedor van con el plan Business: proveedores, compras y órdenes de compra. Todo lo que tenéis ahora sigue funcionando.",
  "print.seeBusiness": "Ver qué incluye Business",
  "print.nothingToPrint": "Aún no hay nada que imprimir",
  "print.pickOrderHint": "Elegid una orden de compra de la lista para previsualizar el documento.",
  "print.pickCustomerOrderHint": "Elegid un pedido de cliente de la lista para previsualizar el documento.",
  "print.pickReturnHint": "Elegid una devolución registrada de la lista para previsualizar el documento.",
  "print.chooseStyleHint": "Elegid un estilo y luego elegid productos de la lista. La vista previa muestra exactamente lo que saldrá de la impresora.",
  "print.howToReach": "Cómo llegar a vuestra impresora",
  "print.howIntro": "Esta aplicación se conecta a impresoras que ya tenéis: no es una impresora en sí misma. Hay cuatro formas de llegar a una, y las etiquetas se imprimen en ambos planes por cualquiera de ellas. Los albaranes de embalaje, las órdenes de compra, los documentos de proveedor y los informes son solo de Business, sea cual sea la conexión.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "Desde esta página, en Chrome o Edge de escritorio y en Chrome de Android: elegid vuestra impresora de etiquetas y las etiquetas van directas a ella. No funciona en Safari de iOS: en un iPhone, la impresión por Bluetooth viene en cambio con la aplicación móvil. Una impresora que solo habla Zebra ZPL o el lenguaje propio de Brother no entenderá las etiquetas que envía esta página; eso se comprueba con impresoras reales antes de darlo por funcionando.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Instalad la impresora en la Wi-Fi de vuestra tienda y luego usad el botón Imprimir: imprime a través de la impresora instalada en este ordenador, por la red de la tienda. En un iPhone, AirPrint viene integrado: una impresora AirPrint en la misma Wi-Fi aparece sin más en la hoja de impresión, sin cable y sin aplicación, y la aplicación no necesita ningún código específico de AirPrint. La impresora debe ser compatible con AirPrint (la mayoría de las nuevas lo son) y el teléfono y la impresora deben estar en la misma Wi-Fi.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Conectad la impresora a la red de vuestra tienda con un cable Ethernet, instaladla en el ordenador e imprimid con el botón Imprimir. Ethernet es una vía de escritorio y de ordenador: los iPhone no usan cables Ethernet.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Conectad la impresora al ordenador con su cable y usad el botón Imprimir: imprime a través de la impresora instalada allí. En un teléfono Android con un cable USB OTG, el botón USB de arriba habla directamente con la impresora. Los iPhone no pueden imprimir por USB directamente (allí no hay WebUSB), así que usad Wi-Fi / AirPrint, o Bluetooth desde la aplicación móvil.",
  "print.howCordsLead": "Los cables siguen sirviendo a los iPhone, a un paso de distancia.",
  "print.howCordsBody": "Una impresora USB conectada al ordenador de la tienda, o una impresora Ethernet conectada a la red, aparece en vuestro iPhone por la Wi-Fi de la tienda (AirPrint / impresora compartida): los cables ponen la impresora en la red con solidez, y el teléfono llega a ella sin cables.",
  "print.howOfflineLead": "Si se cae internet,",
  "print.howOfflineBody": "las etiquetas y documentos que ya están en esta página se siguen imprimiendo: el botón Imprimir, el PDF de etiquetas, Bluetooth y USB no necesitan conexión. Lo que sí necesita internet es cargar la página y sus productos en primer lugar. El modo sin conexión completo (trabajar en la aplicación sin conexión alguna) es un desarrollo aparte y mayor, y no se promete aquí.",
