  "settings.cancelSubscription": "Cancelar suscripción",
  "settings.cancelTerms.appleLink": "Instrucciones de cancelación de Apple",
  "settings.cancelTerms.googlePlayLink": "Instrucciones de cancelación de Google Play",
  "settings.cancelTerms.graceTitle": "Después de que termine su periodo pagado — 15 días de gracia y luego la eliminación:",
  "settings.cancelTerms.intro": "Estas son las condiciones para las suscripciones de pago de Luminous StockHaven. La facturación de la suscripción del sitio web se realiza a través de Stripe. Puede cancelar su suscripción usted mismo en cualquier momento con el botón Cancelar suscripción que aparece a continuación — no se necesita la aprobación del personal. Las solicitudes de cancelación y reembolso también pueden gestionarse a través del contacto oficial de atención al cliente, theluminousbookshop@outlook.com.",
  "settings.cancelTerms.noApprovalBody": "Puede cancelar su suscripción usted mismo en cualquier momento. No se requiere la aprobación del personal. Las renovaciones futuras se detienen solo después de que el proveedor de facturación confirme la cancelación.",
  "settings.cancelTerms.noApprovalTitle": "Cancelar sin aprobación:",
  "settings.cancelTerms.paymentBody": "Para las pruebas de pago, la prueba de siete días requiere un método de pago al registrarse. Salvo que se cancele dentro del plazo de cancelación de la prueba que corresponda, el plan mensual seleccionado se cobrará automáticamente después de la prueba. El precio, la primera fecha de facturación y el plazo de cancelación específico del proveedor deben mostrarse durante el registro. La facturación de la prueba se realiza a través de Stripe.",
  "settings.cancelTerms.paymentTitle": "Método de pago y renovación automática:",
  "settings.cancelTerms.remainingBody": "Si ya ha pagado un periodo de facturación, puede conservar el acceso hasta esa fecha verificada hasta la que está pagado. La terminación anticipada requiere la confirmación adecuada del proveedor y cualquier gestión de reembolso que corresponda. El acceso de la prueba gratuita termina según la fecha de terminación de la prueba confirmada por el proveedor.",
  "settings.cancelTerms.remainingTitle": "Acceso restante:",
  "settings.cancelTerms.storesBody": "Si alguna vez se suscribe a través de Google Play o de la Apple App Store, su suscripción la factura y la gestiona esa tienda. Es posible que deba cancelarla directamente en la sección de suscripciones de la misma cuenta de Google o de Apple utilizada para suscribirse. Cancelar una suscripción independiente del sitio web, desinstalar esta aplicación o solicitar la eliminación de la cuenta de Luminous StockHaven no cancela automáticamente una suscripción facturada por una tienda. Compruebe su recibo de compra para confirmar quién le factura.",
  "settings.cancelTerms.storesTitle": "Suscripciones de Google Play y Apple App Store (si alguna vez se suscribe a través de una tienda):",
  "settings.cancelTerms.title": "Términos y condiciones de cancelación",
  "settings.cancelTerms.trialBody": "La prueba de siete días puede utilizarse solo una vez por cliente que cumpla los requisitos. Cancelar una prueba o una suscripción no otorga otra prueba; los clientes que vuelven deben elegir una suscripción de pago.",
  "settings.cancelTerms.trialTitle": "Una prueba gratuita:",
  "settings.canceled.endsOn": "Esta suscripción está cancelada y termina el {date}. Conserva el acceso completo hasta entonces.",
  "settings.delete.checking": "Comprobando si existe una solicitud de eliminación…",
  "settings.delete.description": "Solicitar la eliminación de su cuenta de acceso a Luminous StockHaven.",
  "settings.delete.dialogDescription": "Esto solicita una revisión de la eliminación de la cuenta. No elimina de inmediato su acceso ni su inventario, y no cancela ninguna suscripción de Stripe. Escriba {word} para confirmar que quiere enviar la solicitud.",
  "settings.delete.dialogTitle": "Solicitar la eliminación de la cuenta",
  "settings.delete.enterDelete": "Escriba {word} para confirmar",
  "settings.delete.exportFirst": "Exporte primero su inventario si necesita conservar sus registros.",
  "settings.delete.intro": "Enviar una solicitud no elimina de inmediato su cuenta, sus negocios ni su inventario. Las solicitudes se revisan por separado antes de que la eliminación pueda completarse. Esta solicitud no cancela una suscripción de Stripe ni detiene la facturación futura; la cancelación de la suscripción debe gestionarse por separado a través del proveedor de facturación.",
  "settings.delete.keepAccount": "Conservar la cuenta",
  "settings.delete.noExport": "Essentials no tiene exportación — anote todo lo que necesite antes de solicitar la eliminación.",
