  "settings.details.address": "Dirección",
  'settings.details.taxRate': 'Mi tasa de impuesto',
  'settings.details.taxRateHint': 'Configúrala una vez. Cada nueva orden de venta calcula su propio impuesto con esta tasa — y aún puedes cambiar el impuesto en cualquier orden individual.',
  "settings.details.taxMode": "Cómo se calcula el impuesto de los pedidos",
  "settings.details.taxModeFixed": "Mi tasa fija",
  "settings.details.taxModeAutomatic": "Automático, según el estado del cliente",
  "settings.details.taxModeHint": "La opción fija usa su tasa en cada pedido nuevo. La automática completa el impuesto de un pedido nuevo con la tasa base estatal del cliente en cuanto el estado está en el pedido, y lo vuelve a completar si el estado cambia. Son tasas base estatales: los impuestos locales pueden agregar más. Un pedido sin estado, o fuera de EE. UU., usa su tasa fija de arriba.",
  'settings.details.gs1Prefix': "Prefijo de empresa GS1",
  'settings.details.gs1PrefixHint': "Solo si tienes una licencia de prefijo de GS1. Ponlo una vez y el generador de códigos del formulario del producto podrá crear códigos UPC y EAN comerciales verdaderos desde tus propios números, cada uno usado una sola vez y nunca reutilizado. Déjalo en blanco si no tienes uno; la aplicación nunca inventa un prefijo.",
  'settings.details.gs1LearnMore': "¿Nuevo en GS1? Si vives en tu propio país, usa su enlace para saber más; si vives en los Estados Unidos, usa el enlace de GS1 US.",
