  "settings.trial.cancelKeeps": "Cancelar durante la prueba le conserva sus 7 días completos — el acceso termina el {date} y no se le hará ningún cargo.",
  "staff.access.noSeatBody": "Su cuenta no tiene un puesto de personal para este negocio, así que sus existencias permanecen cerradas. Pida al propietario que le añada en Personal y roles.",
  "staff.access.noSeatTitle": "Este negocio no está abierto para su acceso",
  "staff.access.pendingBody": "Este negocio tiene una invitación para su correo electrónico que no se ha activado. Pida al propietario que ponga su estado de personal como activo. Nada de esto es visible hasta entonces.",
  "staff.access.pendingTitle": "Su invitación aún no está activa",
  "staff.access.signOut": "Cerrar sesión",
  "staff.access.suspendedBody": "Un administrador ha suspendido esta cuenta de personal para el negocio activo. Pídale que le devuelva el estado activo y vuelva a iniciar sesión.",
  "staff.access.suspendedTitle": "Su acceso está en pausa",
  "staff.addFirst": "Añadir al primer miembro del personal",
  "staff.addMember": "Añadir miembro del personal",
  "staff.emptyBody": "Añada a una persona, asígnele un rol y los permisos correspondientes, y se le invitará por correo electrónico a iniciar sesión en este negocio.",
  "staff.emptyTitle": "Aún no hay personal",
  "staff.eyebrow": "Equipo",
  "staff.how.p1": "Cada miembro tiene un rol y su propia lista de permisos, así que puede partir de un rol y cambiar una sola cosa sin crear un rol nuevo. Editar un rol no reescribe a los miembros que ya lo tienen — abra un miembro para volver a aplicar los valores por defecto de su rol.",
  "staff.how.p2": "Los roles personalizados son una función de Business: Essentials utiliza los cinco roles integrados (Propietario, Gerente, Empleado de almacén, Empleado de ventas, Visualizador).",
  "staff.how.p3": "Las invitaciones se envían por correo electrónico. Un miembro solo puede iniciar sesión una vez que acepta, y quitar a alguien de esta lista no elimina su cuenta de la aplicación.",
  "staff.how.p4": "Una tienda es la ubicación a la que está asignada una persona. Queda registrada en su ficha; lo que puede abrir lo siguen decidiendo su rol y sus permisos.",
  "staff.how.p5": "Los permisos deciden qué puede abrir cada persona: los elementos de menú que quedan fuera de su rol se ocultan, y una dirección bloqueada muestra un aviso de “no está en su rol” en lugar de la página. Un cambio se aplica la próxima vez que esa persona cargue la aplicación; suspender a un miembro le bloquea el acceso por completo.",
  "staff.how.p6": "Los administradores pueden ver y cambiar todos los datos, gestionar los usuarios y roles de la aplicación, y nunca están limitados por un rol de personal. Alguien sin registro de personal — el propietario de un negocio nuevo — conserva el acceso completo.",
  "staff.howTitle": "Cómo funcionan el personal y los roles",
