  "payroll.dd.savings": "Ahorros",
  "payroll.dd.steps.body": "1. Necesitas una cuenta bancaria empresarial que pueda enviar pagos ACH. 2. Recoge un formulario de autorización firmado de cada miembro del equipo: un cheque anulado ayuda a verificar los números. 3. Envía la nómina 2-3 días laborables antes del día de pago para que el dinero llegue a tiempo. 4. La mayoría de los estados exige el consentimiento por escrito del miembro del equipo. Esta aplicación recoge los formularios y te guía paso a paso: el envío del dinero se realiza a través de tu propio banco.",
