  "workforce.unscheduledNote": "Hoy no hay ningún turno programado, así que este tiempo se marcará como sin turno.",
  "workforce.inbox.help": "Eventos de fichaje, respuestas sobre días libres, tareas, recibos de nómina y cambios de horario de tu equipo, los más recientes primero.",
  "workforce.messages.back": "Todas las conversaciones",
