  "training.newForYou": "Formación nueva para ti",
  "training.newForYouHelp": "Estas lecciones se han añadido porque tu rol ha crecido, o porque alguien te las ha asignado. Termínalas para aprender las partes nuevas de la aplicación.",
  "training.noDue": "Sin plazo",
  "training.overdue": "Vencida",
