  "training.steps": "Pasos",
  "training.subtitle": "Aprende cada parte de la aplicación, paso a paso, a tu ritmo. Tus lecciones coinciden con tu rol.",
  "training.team.assign": "Asignar formación",
  "training.team.assignedToast": "Formación asignada.",
