  "auth.sameEmailNotice": "¿Ya tienes nuestra aplicación de Google Play o de la App Store? Usa aquí el mismo correo, aquel con el que inicias sesión en la aplicación, para que tu tienda y tu inventario vengan contigo. Un correo distinto inicia una tienda totalmente nueva y vacía.",
