  "rewards.void": "Anular",
  "rewards.voided": "Recompensa anulada.",
  "workforce.tab.rewards": "Recompensas",
  "training.lessons.mgr-give-rewards.step1": "Abre Equipo y pulsa Recompensas. Elige al miembro del equipo y luego el tipo: un porcentaje de descuento en tienda, una tarjeta regalo u otra cosa que describas con tus propias palabras.",
  "training.lessons.mgr-give-rewards.step2": "Dale a la recompensa un nombre breve y una nota si quieres. La persona recibe un aviso enseguida, y la recompensa la espera en Mis recompensas con su propio código.",
  "training.lessons.mgr-give-rewards.step3": "El límite, por diseño: recompensas SOLO al PERSONAL. No puedes recompensarte a ti mismo ni a otro responsable: recompensar a un responsable es decisión del propietario, y la aplicación se negará con claridad.",
  "training.lessons.mgr-give-rewards.step4": "En caja, escribe el código que te muestre el miembro del equipo y márcalo como utilizado: cada código funciona una vez. Puedes anular una recompensa que hayas dado si cambian los planes; los regalos del propietario son suyos para anularlos.",
  "training.lessons.mgr-give-rewards.title": "Entregar recompensas a tu personal",
  "training.lessons.owner-give-rewards.step1": "Las recompensas están en Equipo, en la pestaña Recompensas, y son solo del plan Business: en Essentials la pestaña Recompensas simplemente no está, igual que todas las partes de la aplicación que son solo de Business.",
  "training.lessons.owner-give-rewards.step2": "Puedes recompensar a CUALQUIERA del equipo, personal y responsables por igual. Elige a la persona y luego el tipo: un porcentaje de descuento en tienda (el porcentaje que elijas), una tarjeta regalo para cualquier sitio o cualquier incentivo que describas con tus propias palabras.",
  "training.lessons.owner-give-rewards.step3": "La recompensa aterriza con su propio código de un solo uso y hace sonar la campana de la persona. Ella muestra el código en caja; un propietario o responsable lo escribe para marcarla como utilizada.",
  "training.lessons.owner-give-rewards.step4": "Un vale de recompensa impreso o compartido lleva solo el nombre de TU negocio, nunca el de la aplicación. Es el agradecimiento de tu tienda, no un anuncio.",
  "training.lessons.owner-give-rewards.title": "Entregar recompensas (plan Business)",
  "training.lessons.owner-rewards-oversight.step1": "Tu responsable también puede entregar recompensas, solo al personal. La aplicación se niega si un responsable se recompensa a sí mismo o a otro responsable; recompensar a un responsable es siempre decisión tuya.",
  "training.lessons.owner-rewards-oversight.step2": "Ves todas las recompensas del negocio en el Historial de recompensas: quién la dio, quién la recibió y si está lista, utilizada o anulada. Un responsable ve solo las recompensas que dio y las que recibió.",
  "training.lessons.owner-rewards-oversight.step3": "Puedes anular cualquier recompensa, incluida una que haya dado tu responsable. Un responsable puede anular sus propios regalos, pero nunca los tuyos.",
  "training.lessons.owner-rewards-oversight.step4": "Cada código funciona exactamente una vez, y una recompensa anulada nunca puede utilizarse: el historial siempre muestra cómo terminó una recompensa.",
  "training.lessons.owner-rewards-oversight.title": "Supervisar las recompensas: lo que entrega tu responsable",
  "training.lessons.staff-your-rewards.step1": "Cuando tu responsable o el propietario te dé una recompensa, tu campana sonará. Abre Equipo y pulsa Recompensas para verla en Mis recompensas.",
  "training.lessons.staff-your-rewards.step2": "Cada recompensa tiene su propio código. Guárdalo para ti: quien muestre el código en caja es quien usa la recompensa.",
  "training.lessons.staff-your-rewards.step3": "Para usarla, muestra el código cuando compres. La persona de caja lo escribe y lo marca como utilizado: cada código funciona exactamente una vez.",
  "training.lessons.staff-your-rewards.step4": "Las recompensas son un gusto del plan Business. Si tu tienda no está en Business, no hay pestaña de Recompensas: así es el plan, no es un error.",
  "training.lessons.staff-your-rewards.title": "Tus recompensas: encontrar tu código y usarlo",
