  "training.lessons.owner-shipping-labels.step1": "El Centro de impresión tiene un estilo de Etiqueta de envío en ambos planes: elija un pedido de cliente e imprima una etiqueta de 4×6 con el nombre y la dirección del comprador y su negocio como remitente.",
  "training.lessons.owner-shipping-labels.step2": "La etiqueta es de marca blanca, como todo documento para el cliente: lleva solo el nombre de su negocio — nunca el nombre de esta aplicación — para que un paquete de su tienda parezca venir de su tienda.",
  "training.lessons.owner-shipping-labels.step3": "La dirección del cliente se guarda con sus pedidos durante 90 días después de su último pedido, y la etiqueta parte de la dirección guardada del pedido cuando tiene una; una dirección escrita al momento de imprimir una etiqueta única no se guarda. El nombre sí se completa desde el pedido, para que la etiqueta coincida con los documentos.",
  "training.lessons.owner-shipping-labels.step4": "La etiqueta se imprime por las mismas cuatro conexiones que todas las etiquetas — Bluetooth, Wi-Fi, Ethernet y USB — y una impresora térmica de 4×6 es el tamaño estándar para ella.",
  "training.lessons.owner-shipping-labels.step5": "¿Compraste el franqueo con el transportista? En esta misma sección puedes subir el archivo de su etiqueta — PDF, PNG o JPG — y quedará guardado en el pedido para siempre: tu registro, a la mano por si pasa algo. Se imprime en su tamaño real de 4×6. La app nunca vende franqueo, así que el precio del transportista es el único precio, y siempre el correcto.",
  "training.lessons.owner-shipping-labels.title": "Etiquetas de envío para pedidos de clientes",
  "training.lessons.print-shipping-label.step1": "Cuando un pedido esté listo para enviarse, abra el Centro de impresión, elija el estilo Etiqueta de envío y después elija el pedido del cliente. El nombre del comprador se completa desde el pedido.",
  "training.lessons.print-shipping-label.step2": "Comprueba la dirección a la que va el paquete. Cuando el pedido trae la dirección del cliente —guardada durante 90 días después de su último pedido— se completa por ti; una dirección que escribes al imprimir no se guarda, así que comprueba el código postal y la última línea con cuidado antes de imprimir.",
  "training.lessons.print-shipping-label.step3": "El nombre de su negocio se imprime arriba como remitente. Si también quiere su dirección en la etiqueta, escríbala en el campo de dirección del remitente; déjelo vacío si prefiere que no aparezca.",
  "training.lessons.print-shipping-label.step4": "Imprima en una etiqueta de 4×6 — una impresora térmica de etiquetas es lo habitual — o en cualquier impresora con el botón de impresión del navegador. Pegue la etiqueta plana sobre el paquete, donde no se doble sobre un borde.",
  "training.lessons.print-shipping-label.step5": "Si el franqueo se compró con el transportista, guarda mejor su archivo de etiqueta en el pedido: sube el PDF, PNG o JPG que te dio el transportista en la sección La etiqueta de tu transportista. Queda en el pedido como tu registro y se imprime en su tamaño real de 4×6, y la etiqueta de dirección de la app siempre está ahí cuando prefieras usarla.",
  "training.lessons.print-shipping-label.title": "Imprima una etiqueta de envío",
