  "staff.memberDialog.settingsAccessHint": "Las secciones marcadas aparecen en la Configuración de esta persona, donde puede verlas y cambiarlas. Las no marcadas quedan ocultas. La suscripción y la facturación nunca están aquí: son solo del propietario.",
