  "login.staffWindowClosed": "La app se abre unos 10 minutos antes de tu turno programado, y todavía no es la hora de tu turno. Vuelve un poco antes de que empiece tu turno.",
  "login.staffWindowClosedNext": "La app se abre unos 10 minutos antes de tu turno programado. Tu próximo turno empieza {when}: vuelve un poco antes.",
  "apiErrors.code.staffOutsideWindow": "La app se abre unos 10 minutos antes de tu turno programado, y todavía no es la hora de tu turno.",
