  "settings.platformPolicies.title": "Políticas de Luminous StockHaven",
  "settings.platformPolicies.description": "Los términos y las políticas propios de la aplicación. Se quedan con la aplicación, y todo el equipo puede leerlos aquí.",
  "staffWelcome.policiesIntro": "Antes de empezar: las políticas y los términos de tu tienda, escritos por el dueño.",
  "plansLib.includes.storePolicies": "Tus propias políticas y términos de tienda en Ajustes, para que los lea todo tu equipo",
  "apiErrors.businessPoliciesOwnerOnly": "Solo el dueño puede cambiar las políticas y los términos de esta tienda.",
  "apiErrors.policyFileInvalid": "Envía un archivo PDF, de texto, de Word o de OpenDocument de menos de 25 MB.",
  "apiErrors.policyTextTooLong": "Ese documento es demasiado largo para escribirlo aquí. Puedes subirlo como archivo en su lugar.",
  "training.lessons.owner-store-policies.title": "Las políticas y términos de tu tienda",
  "training.lessons.owner-store-policies.step1": "Abre Ajustes y busca la tarjeta de Políticas y términos de tu tienda. Guarda dos documentos: las Políticas de tu tienda — las reglas de la casa — y tus Términos y condiciones.",
  "training.lessons.owner-store-policies.step2": "Cada documento se puede escribir ahí mismo, o subirse como archivo (PDF, texto, Word u OpenDocument, de hasta 25 MB). Es una cosa o la otra: guardar el texto reemplaza el archivo, y subir un archivo reemplaza el texto. Quitar un documento lo borra.",
  "training.lessons.owner-store-policies.step3": "Tu equipo ve ambos documentos una vez, en su página de bienvenida cuando empieza, y puede leerlos cuando quiera en sus Ajustes. Para tu equipo son de solo lectura: solo tú puedes escribirlos o cambiarlos.",
  "training.lessons.owner-store-policies.step4": "Cada negocio guarda sus propios documentos: lo que escribes aquí pertenece solo a esta tienda y nunca aparece en otro negocio. Los términos y las políticas propios de Luminous StockHaven viven junto a los tuyos en Ajustes, y todos pueden leerlos también.",
  "training.lessons.welcome-basics.step5": "Las políticas y los términos de tu tienda se muestran una vez en tu página de bienvenida, y viven en Ajustes, donde puedes leerlos cuando quieras.",
  "apiErrors.policyDocNotFound": "Ese documento no es uno de los dos.",
  "apiErrors.policyFileNotFound": "No hay ningún archivo guardado para ese documento.",
  "staffLib.perm.staffRoster": "Ver la lista completa del personal",
  "staffLib.area.staffAccess": "Lista del personal",
  "staff.memberDialog.staffAccessHint": "Solo gerentes — con esta marca, este gerente ve la lista completa del personal, solo para leerla. Sin ella, un gerente solo ve su propia tarjeta. Esta marca no hace nada para el personal.",
  "workforce.schedule.clear": "Borrar",
  "workforce.messages.charCount": "{count} de {max} caracteres",
