  "staffLib.perm.alertsView": "Ver las alertas de existencias bajas",
  "staffLib.perm.productsReorder": "Cambiar los puntos de reorden",
  "staffLib.area.lowStockAccess": "Existencias bajas",
  "staff.memberDialog.lowStockAccessHint": "Con la primera marca, esta persona ve las alertas de existencias bajas — el cuadro de Necesita atención, la página de existencias bajas y las marcas de nivel bajo. Con la segunda marca, puede cambiar el punto de reorden de un producto; sin ella, el campo de punto de reorden sigue a la vista, pero un cambio en él no se guardará.",
  "apiErrors.reorderChangeReserved": "Solo el dueño, o un miembro del equipo al que el dueño haya permitido cambiar los puntos de reorden, puede cambiar un punto de reorden.",
  "apiErrors.alertsViewReserved": "Solo el dueño, o un miembro del equipo al que el dueño haya permitido ver las alertas de existencias bajas, puede ver las alertas de existencias bajas.",
  "apiErrors.quizRequired": "Esta lección termina con un cuestionario corto: respóndelo correctamente para completar la lección.",
