  "training.lessons.your-profile-photo.title": "Tu foto de perfil",
  "training.lessons.your-profile-photo.step1": "Tu foto aparece junto a tu nombre en la parte superior de la aplicación, en la página del personal y junto a tus mensajes — una vez que el propietario la haya aprobado. Hasta entonces, solo se muestran tus iniciales.",
  "training.lessons.your-profile-photo.step2": "Abre Ajustes y busca Tu foto de perfil. Elige una foto tuya y envíala. Va al propietario para que la apruebe — no aparece en ningún sitio mientras espera.",
  "training.lessons.your-profile-photo.step3": "Cuando el propietario la aprueba, suena tu campana y tu foto empieza a mostrarse. Si no se aprueba, elige una foto diferente y envía esa en su lugar.",
  "training.lessons.your-profile-photo.step4": "Cambiar tu foto funciona de la misma manera: la nueva espera la aprobación y tu foto actual permanece en su sitio hasta que la nueva sea aprobada. Si un cambio no se aprueba, te quedas con la otra.",
  "training.lessons.owner-profile-photos.title": "Fotos de perfil y tu nombre",
  "training.lessons.owner-profile-photos.step1": "La foto de cada persona se muestra junto a su nombre en la parte superior de la aplicación, en tu página del personal y junto a sus mensajes. La foto de un miembro del equipo no aparece en ningún sitio hasta que la apruebes — la aprobación es solo tuya, y nadie puede aprobar su propia foto.",
  "training.lessons.owner-profile-photos.step2": "Cuando alguien envía una foto, suena tu campana. Abre la página del personal para verla y luego elige Aprobar o No aprobar. Si no la apruebas, se le dice a la persona que elija otra foto.",
  "training.lessons.owner-profile-photos.step3": "Si una persona cambia su foto, la nueva espera tu aprobación de la misma manera. Su foto actual permanece en su sitio mientras espera — y permanece si no apruebas el cambio.",
  "training.lessons.owner-profile-photos.step4": "Tu propia foto no necesita aprobación: configúrala en Ajustes, en Tu foto de perfil. La misma tarjeta contiene tu nombre — el nombre que establezcas ahí sustituye la palabra Propietario en todas partes donde tu equipo lo ve, en la aplicación y en Mensajes.",
