  "staff.memberDialog.clockAccessHint": "Solo gerentes — dos marcas separadas. Tablero de horas y salidas sin registrar permite a este gerente ver los registros de horas del equipo y corregir registros de horas desde la página de Personal. Llamados permite a este gerente abrir ventanas de llamado, permitir que alguien trabaje cuando no tiene turno programado. Estas marcas no hacen nada para el personal.",
  "workforce.clockGate.closed": "No tienes un turno programado para trabajar ahora, y no hay ninguna ventana de llamado abierta para ti.",
