  "plansLib.businessIncludes.restaurantKitchen": "Restaurante, Cocina y recetas — recetas con descuento automático de ingredientes y costos reales de los platos, hojas de preparación, producción por lotes e ingeniería de menú",
  "plansLib.businessIncludes.restaurantStock": "Restaurante, Inventario y pedidos — niveles de par, la guía de pedidos a proveedores y transferencias entre ubicaciones, además de las hojas de conteo en orden de estantería",
  "plansLib.businessIncludes.restaurantMoney": "Restaurante, Facturas y dinero — facturas de proveedores con verificación triple, alertas de precios, diferencias y la exportación contable, además de las notas de crédito de proveedores",
