  "print.transferReference": "Referencia",
  "print.transferItem": "Artículo",
  "print.transferQuantity": "Cantidad",
  "training.lessons.owner-restaurant-ops.title": "Operaciones de restaurante, para propietarios",
  "training.lessons.owner-restaurant-ops.step1": "Las facturas de proveedores viven en el rincón del restaurante. Introducid lo que facturó un proveedor, vinculado a su pedido de compra, y la aplicación lo verifica de tres maneras — pedido, recibido y facturado, lado a lado — y marca cualquier línea que quede corta, se pase o se facture a un precio distinto.",
  "training.lessons.owner-restaurant-ops.step2": "Cuando una línea de factura cobra un producto a un precio distinto del coste registrado, se abre una alerta de precio en la página de facturas. Aceptar una alerta actualiza el coste del producto al precio facturado; descartarla deja el coste como estaba.",
  "training.lessons.owner-restaurant-ops.step3": "El registro de desperdicios anota todo lo que tira la cocina, con un motivo — deterioro, sobreproducción, un error de preparación, una devolución, un derrame u otro — y registrarlo descuenta las existencias de la estantería por sí solo. Los lotes de caducidad se listan en orden de primero en caducar, primero en usarse, para que se use primero la fecha de caducidad más cercana, y podéis imprimir etiquetas de fecha para los lotes que marquéis.",
  "training.lessons.owner-restaurant-ops.step4": "La matriz de alérgenos calcula los alérgenos de cada plato desde los ingredientes de su receta, frente a los nueve alérgenos principales, para que la pregunta de un cliente se responda desde el registro, no de memoria. Los registros de temperatura, el tablero de agotados y las comidas del personal están abiertos a todo el equipo — sin necesidad de ninguna marca — porque el registro diario solo funciona cuando cualquiera puede hacerlo.",
  "training.lessons.owner-restaurant-ops.step5": "La ingeniería de menú ubica cada plato según cuánto se vendió y cuánto dejó: estrellas, caballos de tiro, rompecabezas y perros. La página de diferencias compara lo que las recetas dicen que debió salir de la estantería con las comidas del personal, los desperdicios y todo lo demás que salió — lo que sobra queda sin explicar. La exportación contable reúne compras recibidas, desperdicios, comidas del personal y consumo de recetas en un solo libro para vuestros libros.",
  "training.lessons.staff-restaurant-daily.title": "Los hábitos diarios de la cocina",
  "training.lessons.staff-restaurant-daily.step1": "Cuando algo se tire, registradlo en el registro de desperdicios el mismo día: qué era, cuánto y el motivo — deterioro, sobreproducción, un error de preparación, una devolución, un derrame u otro. Registrarlo descuenta las existencias de la estantería por sí solo; no ajustéis las existencias por separado.",
  "training.lessons.staff-restaurant-daily.step2": "Registrad cada temperatura de frigorífico, congelador y mantenimiento en caliente cuando la reviséis. El registro guarda vuestro nombre y la hora, y marca cualquier lectura fuera del rango seguro — escribid qué hicisteis al respecto como acción correctiva.",
  "training.lessons.staff-restaurant-daily.step3": "El tablero de agotados es lo que está agotado, ahora mismo. Publicad un artículo en el momento en que se acabe, para que todo el equipo lo sepa al instante, y quitadlo cuando vuelva — el tablero guarda quién lo quitó y cuándo.",
  "training.lessons.staff-restaurant-daily.step4": "Cuando el equipo coma, registradlo como una comida del personal. Cada comida descuenta su plato de la estantería y usa los ingredientes de la receta del plato, igual que una venta. Una comida del personal es un coste real del día y pertenece al registro.",
  "training.lessons.mgr-restaurant-invoices.title": "Facturas, lotes y producciones por lote",
  "training.lessons.mgr-restaurant-invoices.step1": "El propietario os ha confiado la marca Crear recetas, y también abre el trabajo de construcción de la cocina: facturas de proveedores, lotes de caducidad y producción por lotes. Introducid una factura de proveedor con sus líneas — el producto, la cantidad y el coste facturado — y vinculadla a su pedido de compra cuando haya uno.",
  "training.lessons.mgr-restaurant-invoices.step2": "Con un pedido de compra vinculado, la factura se verifica de tres maneras, línea por línea: lo que se pidió, lo que se recibió y lo que se facturó. Una línea puede resultar coincidente, corta, excedida, facturada a un precio distinto o no estar en el pedido en absoluto.",
  "training.lessons.mgr-restaurant-invoices.step3": "Cuando un precio facturado difiere del coste registrado del producto, se abre una alerta de precio. Aceptar la alerta fija el coste del producto en el nuevo precio facturado; descartarla no cambia nada. Solo puede haber una alerta abierta a la vez para la misma factura y el mismo producto.",
  "training.lessons.mgr-restaurant-invoices.step4": "Recibid existencias como un lote de caducidad con su fecha de caducidad, y la página de caducidades mantiene los lotes en orden de primero en caducar, primero en usarse. Una producción por lote prepara una receta un número determinado de veces: consume los ingredientes de la receta y pone el producto de preparación terminado en la estantería — la receta debe estar vinculada primero a ese producto de preparación.",
  "training.lessons.mgr-restaurant-invoices.step5": "Cuando un proveedor devuelve dinero contra una factura — una caja dañada, una entrega corta, un precio corregido — regístralo como una nota de crédito en la página de facturas, contra esa factura. El proveedor viene de la propia factura, y la nota cuenta contra lo que aún se debe de la factura: la factura muestra su crédito aplicado y su saldo pendiente. Un crédito nunca puede ser mayor que su factura, y anular una nota la mantiene en el registro mientras deja de contar. Imprime la nota desde su fila cuando la necesites en papel: la hoja impresa es tu propio registro del crédito del proveedor, no el documento del proveedor.",
  "training.lessons.mgr-restaurant-reports.title": "Ingeniería de menú, diferencias y los libros",
  "training.lessons.mgr-restaurant-reports.step1": "El propietario os ha confiado la marca Dinero de los platos, y también abre los informes de dinero de la cocina: ingeniería de menú, diferencias y la exportación contable. Estas cifras se quedan dentro del negocio, como todo el dinero de los platos.",
  "training.lessons.mgr-restaurant-reports.step2": "La ingeniería de menú ubica cada plato según cuánto se vendió y cuánto dejó en el período. Las estrellas se venden bien y dejan bien; los caballos de tiro se venden bien pero dejan poco; los rompecabezas dejan bien pero se venden poco; los perros no hacen ni lo uno ni lo otro.",
  "training.lessons.mgr-restaurant-reports.step3": "La página de diferencias trabaja por producto: lo que las recetas dicen que debió salir de la estantería, junto a las comidas del personal, los desperdicios y toda otra salida de existencias. Lo que sobre queda sin explicar — y lo sin explicar es el número que hay que ir a explicar.",
  "training.lessons.mgr-restaurant-reports.step4": "La exportación contable es un solo libro para la cocina: compras recibidas, desperdicios, comidas del personal y consumo de recetas, cada fila con su fecha, cantidad y coste, lista para entregarla a quien lleve vuestros libros.",
  "apiErrors.invalidReference.recipeMustBelongBusiness": "La receta debe pertenecer a este negocio.",
  "apiErrors.invalidReference.purchaseOrderMustBelongBusiness": "El pedido de compra debe pertenecer a este negocio.",
