  "storefronts.disconnectNote": "Al desconectar, dejan de llegar ventas nuevas. Las ventas ya registradas permanecen en tu historial.",
  "storefronts.ebayDesc": "Conecta tu tienda de eBay una sola vez. Cuando un artículo se vende en eBay, su cantidad baja aquí por sí sola, con la venta registrada en tus movimientos — igual que si se hubiera escaneado al salir. Las ventas fluyen en un solo sentido: de eBay hacia la aplicación.",
