  "training.own.markPass": "Marcar como aprobada",
  "training.own.sectionTitle": "Capacitaciones de su propietario",
  "training.own.sectionHelp": "Su propietario escribió estas capacitaciones para esta tienda. Lea cada una y luego responda las preguntas de su propietario.",
  "training.own.read": "La capacitación",
  "training.own.noMaterial": "El propietario aún no ha agregado el texto de la capacitación.",
  "training.own.pendingNote": "Sus respuestas están con el propietario. Esta capacitación cuenta como terminada cuando el propietario la marca como aprobada.",
  "plansLib.includes.ownTraining": "Agregue su propia capacitación — escriba sus propias capacitaciones y cuestionarios para su equipo",
  "training.lessons.owner-own-training.title": "Cómo agregar su propia capacitación",
  "training.lessons.owner-own-training.step1": "Al final de la página de Capacitación está el cuadro Agregue su propia capacitación. Ábralo, inicie una nueva capacitación y póngale un título — sus reglas de seguridad, sus precauciones, su manera de hacer las cosas.",
  "training.lessons.owner-own-training.step2": "Escriba la capacitación en el cuadro, con sus propias palabras, o súbala como archivo — un archivo PDF, de texto, de Word o de OpenDocument. Las palabras escritas reemplazan un archivo guardado, y un archivo reemplaza las palabras escritas.",
  "training.lessons.owner-own-training.step3": "Cree su cuestionario debajo: tantas preguntas como quiera, de opción múltiple y de respuesta escrita mezcladas libremente. Para una pregunta escrita, escriba la respuesta que espera; para opción múltiple, marque la correcta.",
  "training.lessons.owner-own-training.step4": "Fije la línea de aprobación y elija cómo se juzgan las respuestas escritas: revisadas contra su clave de respuestas casi palabra por palabra, o enviadas a usted para aprobarlas o devolverlas. Luego marque exactamente qué miembros del equipo toman esta capacitación — solo ellos la ven.",
  "training.lessons.owner-own-training.step5": "Cada capacitación que guarda queda por su cuenta en el cuadro, con sus propias preguntas, línea y marcas, y puede agregar tantas como quiera. Los resultados llegan al cuadro debajo de cada capacitación; una capacitación cuenta como terminada solo cuando el servidor ha verificado un intento aprobado — o, en modo de calificar, cuando usted la marca como aprobada.",
  "apiErrors.ownTrainingOwnerWrites": "Solo el propietario escribe estas capacitaciones.",
  "apiErrors.ownTrainingNotHere": "Esa capacitación no está aquí.",
  "apiErrors.ownTrainingTooLong": "Esa capacitación es demasiado larga para escribirla aquí. Puede subirla como archivo en su lugar.",
  "apiErrors.ownTrainingTicksList": "Envíe a las personas marcadas como una lista.",
  "apiErrors.ownTrainingTickNotTeam": "Una de las personas marcadas no está en este equipo.",
  "apiErrors.ownTrainingNoFile": "No hay ningún archivo guardado para esa capacitación.",
  "apiErrors.ownTrainingWrittenMode": "Las respuestas escritas se revisan contra la clave o se envían al propietario.",
  "print.pool.title": "Generar códigos de barras",
  "print.pool.intro": "Crea códigos de barras antes de que existan los productos. Imprímelos, pégalos en artículos que no tienen código propio, y cuando uno se escanee más tarde la aplicación reconocerá el código y ofrecerá agregar el producto.",
  "print.pool.countLabel": "¿Cuántos códigos de barras necesitas?",
  "print.pool.generate": "Generar",
  "print.pool.generating": "Generando…",
  "print.pool.minted": "{count} códigos de barras nuevos se agregaron a tu reserva.",
  "print.pool.waiting": "{count} códigos de barras sin usar esperan en tu reserva.",
  "print.pool.printNow": "Imprimirlos ahora",
  "print.pool.savePdf": "Guardar como PDF",
  "print.pool.failed": "Esos códigos de barras no se pudieron crear. Inténtalo de nuevo.",
  "scan.pool.title": "Uno de tus propios códigos de barras impresos",
  "scan.pool.body": "Esto aún no es un producto de tu tienda: es un código de barras que imprimiste con anticipación. ¿Quieres agregarlo como producto?",
  "plansLib.includes.barcodePool": "Reserva de códigos de barras: imprime códigos por adelantado y agrega cada producto cuando se escanee su código",
  "training.lessons.owner-barcode-pool.title": "Imprimir códigos de barras antes que los productos",
  "training.lessons.owner-barcode-pool.step1": "Algunos artículos no tienen código de barras propio: piezas hechas a mano, tus propias bolsas para libros, cualquier cosa que hagas o armes tú. En la sección Imprimir, la puerta Generar códigos de barras crea códigos antes de que existan los productos.",
  "training.lessons.owner-barcode-pool.step2": "Di cuántos necesitas — no hay límite — y la aplicación creará esa cantidad de códigos nuevos en la reserva de códigos de tu negocio. Pertenecen solo a tu negocio, nunca se entregan dos veces, y crearlos no genera productos ni existencias.",
  "training.lessons.owner-barcode-pool.step3": "En el momento en que se crean, elige: imprimirlos ahora como etiquetas o guardarlos como PDF para imprimirlos después. De cualquier manera los códigos quedan en la reserva, y las etiquetas impresas coinciden exactamente con ella.",
  "training.lessons.owner-barcode-pool.step4": "Pega una etiqueta en cada artículo a medida que lo haces. Los códigos sin usar simplemente esperan en la reserva: no hay prisa y no caducan.",
  "training.lessons.owner-barcode-pool.step5": "Cuando un artículo con etiqueta se escanea más tarde, la aplicación reconoce su propio código impreso y ofrece agregar el producto, con el código ya completado. Una vez agregado, el código es el código de ese producto y se escanea como cualquier otro.",
  "apiErrors.poolOwnerMints": "Solo el propietario crea códigos de barras para la reserva.",
  "apiErrors.poolCount": "Di cuántos códigos de barras necesitas: un número entero de uno o más.",
