  "training.lessons.staff-checklists.title": "Trabajar una lista de verificación",
  "training.lessons.staff-checklists.step1": "Las listas de verificación son las listas con las que funciona tu negocio: apertura, cierre, limpieza y todo lo demás que el propietario configure. Encuéntralas en Listas de verificación: las de hoy están arriba, listas para marcar.",
  "training.lessons.staff-checklists.step2": "Marca un punto cuando realmente lo hayas hecho. Cada marca anota quién lo hizo y cuándo, para que la siguiente persona — y el propietario desde casa — vean qué está hecho y qué falta.",
  "training.lessons.staff-checklists.step3": "Algunos puntos piden una prueba antes de poder marcarse: una foto del trabajo terminado, un escaneo de un código o una temperatura escrita. Agrega primero la prueba y luego marca: el punto no se marcará sin ella.",
  "training.lessons.staff-checklists.step4": "¿Marcaste algo por error? Desmárcalo, pero solo tus propias marcas. Un gerente o el propietario pueden desmarcar las de cualquiera, porque una marca es un registro con un nombre.",
  "training.lessons.staff-checklists.step5": "Nunca necesitas permiso para trabajar una lista. Crear las plantillas y elegir a quién se asignan es trabajo del propietario, o de una persona a la que el propietario haya dado la marca de plantillas de listas.",
